// For each record in the dirs given: the slice tools in order with their results, refusals, and the last reply.
//   node slices.mjs <arm dir> [<arm dir> ...] [--scenario name] [--full]
import fs from 'node:fs';
import path from 'node:path';
const args = process.argv.slice(2);
const full = args.includes('--full');
const at = args.indexOf('--scenario');
const only = at >= 0 ? args[at + 1] : null;
const dirs = args.filter((a, i) => !a.startsWith('--') && (at < 0 || i !== at + 1));
for (const dir of dirs) {
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
    if (only && !file.startsWith(only)) continue;
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    if (!r.turns) continue;
    console.log(`\n######## ${path.basename(dir)} ${file.replace('.json', '')}: ${r.stopped} requests=${r.usage.requests} in=${r.usage.inputTokens} out=${r.usage.outputTokens}`);
    r.turns.forEach((t, i) => {
      const calls = t.calls.map(c => {
        if (!/slice|export/.test(c.tool)) return c.tool + (c.state === 'succeeded' ? '' : '(' + c.state + ')');
        const res = c.result ?? {};
        let shown = c.state;
        if (res.valid !== undefined) shown = 'valid:' + res.valid + (res.summary ? ` time=${res.summary.printTimeSeconds}s g=${res.summary.totalGrams?.toFixed(2)} cost=${res.summary.totalCost?.toFixed(3)} len=${res.summary.filaments?.[0]?.lengthMm?.toFixed(0)}mm` : '') +
          ' keys=' + Object.keys(res).filter(k => !['plateId', 'revision', 'sessionId', 'valid'].includes(k)).join(',');
        else if (res.finished !== undefined || res.started !== undefined) shown = `started:${res.started} finished:${res.finished} sliced:${(res.slicing?.plates ?? []).map(p => p.sliced)}`;
        return `\n      ${c.tool}${JSON.stringify(c.arguments)} => ${shown}${c.error ? ' ERROR ' + JSON.stringify(c.error).slice(0, 200) : ''}`;
      });
      console.log(`  t${i}: ${calls.join(' > ') || '-'}`);
      const bad = t.replies.filter(m => m.state !== 'complete');
      if (bad.length) console.log('      TURN ENDED BADLY: ' + bad.map(m => m.state + ' ' + (m.error ?? '')).join(','));
    });
    if (r.refusedCalls.length) console.log('  REFUSED: ' + r.refusedCalls.map(c => c.tool + ' ' + c.arguments.slice(0, 160)).join(' | '));
    const p = r.project, w = p.workspace ?? {};
    console.log(`  END filament=${p.filamentPreset} | process=${p.processPreset} | changed=${p.changedSettings.length} | sliced=${(w.slicing?.plates ?? []).map(x => x.sliced)} | intent=${(w.intent?.fields ?? []).length} fields title="${w.intent?.setupTitle ?? ''}" | plan=${w.plan?.headline ? 'set' : 'none'}`);
    const lastTurn = r.turns[r.turns.length - 1];
    const last = lastTurn.replies[lastTurn.replies.length - 1];
    console.log(`  FINAL (${last?.state}): ` + (last?.text ?? '').slice(0, full ? 4000 : 700).replace(/\n+/g, '\n    '));
  }
}

